def find_construction(n, k):
    if k > n // 2:
        return "NO"

    s = [0] * n
    imbalanced_count = 0

    for i in range(n):
        if i % 2 == 0:
            s[i] = i // 2 + 1
        else:
            s[i] = (i + 1) // 2

        if s[i] != 0 and s[i] != i + 1:
            imbalanced_count += 1

        if imbalanced_count > k:
            return "NO"

    if imbalanced_count == k:
        return "YES\n" + " ".join(map(str, s))
    else:
        return "NO"

